/// Validate that a parsed YAML value is a mapping.
///
/// Config files must be YAML mappings at the top level. This rejects
/// null (empty / comments-only files), scalars, and sequences with a
/// clear error message so the user knows their config wasn't loaded.
fn validate_yaml_mapping(value: &serde_yaml::Value, source_path: &Path) -> Result<()> {
    if value.is_null() {
        return Err(BivvyError::ConfigParseError {
            path: source_path.to_path_buf(),
            message: "config file is empty or contains only comments".to_string(),
        });
    }
    if !value.is_mapping() {
        let type_name = match value {
            serde_yaml::Value::Bool(_) => "a boolean",
            serde_yaml::Value::Number(_) => "a number",
            serde_yaml::Value::String(_) => "a string",
            serde_yaml::Value::Sequence(_) => "a sequence (list)",
            serde_yaml::Value::Tagged(_) => "a tagged value",
            _ => "a non-mapping value",
        };
        return Err(BivvyError::ConfigParseError {
            path: source_path.to_path_buf(),
            message: format!(
                "expected a YAML mapping at the top level, but found {type_name}"
            ),
        });
    }
    Ok(())
}

