"#;

/// Config with custom step prompts (select, confirm, input).
/// Uses real commands to exercise actual tool behavior.
const CUSTOM_PROMPTS_CONFIG: &str = r#"
app_name: "PromptApp"
steps:
  deploy:
    title: "Deploy"
