    steps: [normal, secrets]
"#;

/// Config with no check (formerly marker type).
const MARKER_CHECK_CONFIG: &str = r#"
app_name: "MarkerApp"
steps:
  setup:
    title: "Setup step"
    command: "rustc --version && uname -s"
    skippable: false
workflows:
